'use client'

import { createContext, useContext, type ComponentProps, type ReactNode } from 'react'
import { cn } from '@/lib/utils'
import styles from './TopBar.module.css'

/**
 * What the shell's pieces need from the App Shell around them: the brand,
 * whether it takes a sidebar-wide cell, where a NavSidebar's top row puts
 * it, and whether the shell is narrower than 64rem, where a NavSidebar is
 * the icon rail. Outside a shell, none of it applies.
 */
export const ShellContext = createContext<{
  brand: ReactNode
  brandCell: boolean
  isNarrow: boolean
  /** The logo for a NavSidebar's top row: the sidebar layout, while the sidebar is expanded. */
  sidebarBrand: ReactNode
}>({
  brand: null,
  brandCell: false,
  isNarrow: false,
  sidebarBrand: null,
})

/** `null`, `false` and `undefined` render nothing. */
const given = (node: ReactNode) => node != null && node !== false

export interface TopBarProps extends ComponentProps<'header'> {
  /** Breadcrumbs, or TopBarNav links. */
  start?: ReactNode
  /** Search, notifications, the account menu. */
  end?: ReactNode
  children?: ReactNode
}

/** The bar above the page. Inside an App Shell it shows the shell's brand. */
export function TopBar({ start, end, children, className, ...props }: TopBarProps) {
  const shell = useContext(ShellContext)
  return (
    <header className={cn(styles.header, className)} data-brand-cell={shell.brandCell || undefined} {...props}>
      {given(shell.brand) && <div className={styles.brand}>{shell.brand}</div>}
      {start && <div className={styles.start}>{start}</div>}
      {children && <div className={styles.center}>{children}</div>}
      {end && <div className={styles.end}>{end}</div>}
    </header>
  )
}

export interface TopBarNavItem {
  label: string
  href: string
}

export interface TopBarNavProps extends Omit<ComponentProps<'nav'>, 'children'> {
  items: TopBarNavItem[]
  /** The href of the page you are on. */
  currentHref?: string
  'aria-label'?: string
}

/** Navigation links across the Top Bar. When they do not fit, they scroll sideways. */
export function TopBarNav({ items, currentHref, className, 'aria-label': ariaLabel = 'Main', ...props }: TopBarNavProps) {
  return (
    <nav aria-label={ariaLabel} className={cn(styles.nav, className)} {...props}>
      <ul>
        {items.map((item) => (
          <li key={item.href}>
            <a href={item.href} className={styles.navLink} aria-current={item.href === currentHref ? 'page' : undefined}>
              {item.label}
            </a>
          </li>
        ))}
      </ul>
    </nav>
  )
}

/* The Top Bar pattern: the row only. Its fill and edge belong to the App
   Shell's top cell, which also is the size container its queries read. */
.header {
  display: flex;
  align-items: center;
  gap: var(--space-group);
  min-block-size: var(--shell-bar, calc(var(--control-md) + 2 * var(--space-cluster)));
  padding-inline: var(--space-4);
}
@container (min-width: 64rem) {
  .header {
    padding-inline: var(--space-section);
  }
}

.brand {
  display: flex;
  align-items: center;
  min-inline-size: 0;
}

.start {
  display: flex;
  align-items: center;
  gap: var(--space-8);
  min-inline-size: 0;
}
.center {
  flex: 1;
  min-inline-size: 0;
}
.end {
  display: flex;
  align-items: center;
  gap: var(--space-inline);
  margin-inline-start: auto;
}

/* Over a sidebar (the shell's top-bar layout), the logo takes a cell as wide
   as the sidebar, so it sits where it sits in the sidebar layout. */
@container (min-width: 64rem) {
  .header[data-brand-cell] {
    padding-inline-start: 0;
  }
  .header[data-brand-cell] .brand {
    box-sizing: border-box;
    flex: none;
    inline-size: var(--sidebar-width);
    padding-inline-start: var(--shell-logo-x, calc(2 * var(--space-inline)));
  }
}

/* ----------------------------------------------------------------- nav */
.nav ul {
  display: flex;
  gap: var(--space-1);
  margin: 0;
  padding: 0;
  list-style: none;
}
/* Links that do not fit scroll sideways, rather than squeeze the bar. The
   padding, taken back by the margin, keeps a focus ring inside the scroller,
   which clips what overflows it. */
.nav {
  --nav-ring: calc(var(--focus-width) + var(--focus-offset));
  min-inline-size: 0;
  margin: calc(-1 * var(--nav-ring));
  padding: var(--nav-ring);
  overflow-x: auto;
  scrollbar-width: none;
}

.navLink {
  display: inline-flex;
  align-items: center;
  min-block-size: calc(var(--space-8) + var(--space-1));
  padding-inline: var(--space-3);
  border-radius: var(--radius-field);
  color: var(--muted-foreground);
  font-size: var(--text-body);
  font-weight: 500;
  text-decoration: none;
  white-space: nowrap;
}
.navLink:hover {
  background: var(--accent);
  color: var(--accent-foreground);
}
.navLink:focus-visible {
  outline: var(--focus-width) solid var(--ring);
  outline-offset: var(--focus-offset);
}
/* The current page: foreground text on the subtle surface, not colour alone. */
.navLink[aria-current='page'] {
  background: var(--accent);
  color: var(--foreground);
}
